<script>$(function(){var items=@json($items),places={{ $decimalPlaces }};var body=$('#opening-lines tbody'),n=0;function syncWarehouses(){var branch=$('#opening-branch').val(),select=$('#opening-warehouse'),current=select.val();select.find('option[data-branch-id]').each(function(){var show=!branch||String($(this).data('branch-id'))===String(branch);$(this).toggle(show).prop('disabled',!show);});if(current&&select.find('option[value="'+current+'"]').prop('disabled'))select.val('');}$('#opening-branch').on('change',syncWarehouses);syncWarehouses();function add(){var i=n++,opts=items.map(function(x){return '<option value="'+x.id+'" data-uom="'+x.uom_id+'" data-uom-label="'+(x.uom_label||'')+'">'+x.label+'</option>';}).join('');body.append('<tr><td><select class="form-select js-item" name="lines['+i+'][item_id]" required><option value="">เลือกสินค้า</option>'+opts+'</select><input type="hidden" class="js-uom-id" name="lines['+i+'][uom_id]"></td><td class="js-uom-label">—</td><td><input class="form-control js-qty" type="number" min="0.00000001" step="any" name="lines['+i+'][quantity]" required></td><td><input class="form-control js-total-input" type="number" min="0" step="any" name="lines['+i+'][total_value]" required></td><td class="text-end js-unit-cost">0</td><td class="text-end js-total-display">0</td><td class="text-end"><button type="button" class="btn btn-sm btn-outline-danger js-remove">ลบ</button></td></tr>');}function fmt(v){return Number(v||0).toLocaleString(undefined,{minimumFractionDigits:places,maximumFractionDigits:places});}function calc(r){var q=parseFloat(r.find('.js-qty').val())||0,t=parseFloat(r.find('.js-total-input').val())||0;r.find('.js-unit-cost').text(fmt(q>0?t/q:0));r.find('.js-total-display').text(fmt(t));}$('#add-opening-line').on('click',add);body.on('change','.js-item',function(){var o=$(this).find(':selected'),r=$(this).closest('tr');r.find('.js-uom-id').val(o.data('uom')||'');r.find('.js-uom-label').text(o.data('uom-label')||'—');});body.on('input','.js-qty,.js-total-input',function(){calc($(this).closest('tr'));});body.on('click','.js-remove',function(){$(this).closest('tr').remove();});add();$('#opening-balance-form').on('submit',function(e){e.preventDefault();var f=$(this),b=f.find('button[type=submit]').prop('disabled',true);$.ajax({url:f.attr('action'),method:'POST',data:f.serialize(),headers:{Accept:'application/json'}}).done(function(r){window.location=r.redirect;}).fail(function(xhr){alert(xhr.responseJSON?.message||'บันทึกไม่สำเร็จ');}).always(function(){b.prop('disabled',false);});});});</script>
